export const deleteLoadBalancersIdRoute = createRoute({
  method: 'delete',
  path: '/load_balancers/{id}',
  tags: ['Load Balancers'],
  summary: 'Delete a Load Balancer',
  description: 'Deletes a Load Balancer.',
  request: {
    params: z.object({
      id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: 'ID of the Load Balancer',
            in: 'path',
            name: 'id',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: { 204: { description: 'Load Balancer deleted' } },
})

