export const getLoadBalancersIdMetricsRoute = createRoute({
  method: 'get',
  path: '/load_balancers/{id}/metrics',
  tags: ['Load Balancers'],
  summary: 'Get Metrics for a LoadBalancer',
  description:
    'You must specify the type of metric to get: `open_connections`, `connections_per_second`, `requests_per_second` or `bandwidth`. You can also specify more than one type by comma separation, e.g. `requests_per_second,bandwidth`.\n\nDepending on the type you will get different time series data:\n\n|Type | Timeseries | Unit | Description |\n|---- |------------|------|-------------|\n| open_connections | open_connections | number | Open connections |\n| connections_per_second | connections_per_second | connections/s | Connections per second |\n| requests_per_second | requests_per_second | requests/s | Requests per second |\n| bandwidth | bandwidth.in | bytes/s | Ingress bandwidth |\n|| bandwidth.out | bytes/s | Egress bandwidth |\n\nMetrics are available for the last 30 days only.\n\nIf you do not provide the step argument we will automatically adjust it so that 200 samples are returned.\n\nWe limit the number of samples to a maximum of 500 and will adjust the step parameter accordingly.\n',
  request: {
    params: z.object({
      id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: 'ID of the Load Balancer',
            in: 'path',
            name: 'id',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
    query: z.object({
      type: z
        .enum(['open_connections', 'connections_per_second', 'requests_per_second', 'bandwidth'])
        .openapi({
          param: {
            description: 'Type of metrics to get',
            in: 'query',
            name: 'type',
            required: true,
            schema: {
              enum: [
                'open_connections',
                'connections_per_second',
                'requests_per_second',
                'bandwidth',
              ],
              type: 'string',
            },
          },
        }),
      start: z
        .string()
        .openapi({
          param: {
            description: 'Start of period to get Metrics for (in ISO-8601 format)',
            in: 'query',
            name: 'start',
            required: true,
            schema: { type: 'string' },
          },
        }),
      end: z
        .string()
        .openapi({
          param: {
            description: 'End of period to get Metrics for (in ISO-8601 format)',
            in: 'query',
            name: 'end',
            required: true,
            schema: { type: 'string' },
          },
        }),
      step: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Resolution of results in seconds',
            in: 'query',
            name: 'step',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The `metrics` key in the reply contains a metrics object with this structure',
      content: {
        'application/json': {
          schema: z
            .object({
              metrics: z
                .object({
                  end: z
                    .string()
                    .openapi({
                      description: 'End of period of metrics reported (in ISO-8601 format)',
                      example: '2017-01-01T23:00:00+00:00',
                    }),
                  start: z
                    .string()
                    .openapi({
                      description: 'Start of period of metrics reported (in ISO-8601 format)',
                      example: '2017-01-01T00:00:00+00:00',
                    }),
                  step: z
                    .number()
                    .openapi({ description: 'Resolution of results in seconds.', example: 60 }),
                  time_series: z
                    .record(
                      z.string(),
                      z
                        .object({
                          values: z
                            .array(z.array(z.xor([z.number(), z.string()])))
                            .openapi({ description: 'Metrics Timestamps with values' }),
                        })
                        .openapi({ required: ['values'] }),
                    )
                    .openapi({
                      description:
                        'Hash with timeseries information, containing the name of timeseries as key',
                      example: {
                        name_of_timeseries: {
                          values: [
                            [1435781470.622, '42'],
                            [1435781471.622, '43'],
                          ],
                        },
                      },
                    }),
                })
                .openapi({ required: ['start', 'end', 'step', 'time_series'] }),
            })
            .openapi({ required: ['metrics'] }),
        },
      },
    },
  },
})

