export const deleteServersIdRoute = createRoute({
  method: 'delete',
  path: '/servers/{id}',
  tags: ['Servers'],
  summary: 'Delete a Server',
  description:
    'Deletes a Server. This immediately removes the Server from your account, and it is no longer accessible.',
  request: {
    params: z.object({
      id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: 'ID of the Server',
            in: 'path',
            name: 'id',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The `action` key in the reply contains an Action object with this structure',
      content: {
        'application/json': {
          schema: z
            .object({
              action: z
                .object({
                  command: z
                    .string()
                    .openapi({
                      description: 'Command executed in the Action',
                      example: 'start_server',
                    }),
                  error: z
                    .object({
                      code: z
                        .string()
                        .openapi({
                          description: 'Fixed machine readable code',
                          example: 'action_failed',
                        }),
                      message: z
                        .string()
                        .openapi({
                          description: 'Humanized error message',
                          example: 'Action failed',
                        }),
                    })
                    .nullable()
                    .openapi({
                      description: 'Error message for the Action if error occurred, otherwise null',
                      required: ['code', 'message'],
                    }),
                  finished: z
                    .string()
                    .nullable()
                    .openapi({
                      description:
                        'Point in time when the Action was finished (in ISO-8601 format). Only set if the Action is finished otherwise null.',
                      example: '2016-01-30T23:55:00+00:00',
                    }),
                  id: z.int().openapi({ description: 'ID of the Resource', example: 42 }),
                  progress: z
                    .number()
                    .openapi({ description: 'Progress of Action in percent', example: 100 }),
                  resources: z
                    .array(
                      z
                        .object({
                          id: z.int().openapi({ description: 'ID of the Resource', example: 42 }),
                          type: z
                            .string()
                            .openapi({
                              description: 'Type of resource referenced',
                              example: 'server',
                            }),
                        })
                        .openapi({ required: ['id', 'type'] }),
                    )
                    .openapi({ description: 'Resources the Action relates to' }),
                  started: z
                    .string()
                    .openapi({
                      description: 'Point in time when the Action was started (in ISO-8601 format)',
                      example: '2016-01-30T23:55:00+00:00',
                    }),
                  status: z
                    .enum(['success', 'running', 'error'])
                    .openapi({ description: 'Status of the Action' }),
                })
                .exactOptional()
                .openapi({
                  required: [
                    'id',
                    'command',
                    'status',
                    'progress',
                    'started',
                    'finished',
                    'resources',
                    'error',
                  ],
                  title: 'Action',
                }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
})

